"""Astronomer blueprint wrapping DatabricksRunNowOperator.

Loaded by the team's `dags_loader.py` when a `.dag.yaml` file declares
`blueprint: ".blueprints.databricks_dbt"`. Reads `params` from the DAG
config and constructs a DatabricksRunNowOperator task.

OQ-2 tracks whether Catalyst owns this blueprint long-term or each team
authors their own.
"""
from airflow import DAG
from airflow.providers.databricks.operators.databricks import DatabricksRunNowOperator


def build_dag(dag_id, params, default_args, schedule, catchup, tags, start_date, render_template_as_native_obj):
    """Construct a DAG running a single Databricks job.

    Args:
        dag_id: DAG identifier (e.g., "client_positions__daily_positions__daily").
        params: dict with databricks_conn_id, job_name, partition_key,
                pool, pool_slots, (optional) sla_minutes.
        default_args: Airflow default args (retries, callbacks, etc.).
        schedule: Asset list or cron string.
        catchup: bool, must be False per RFD 0011 §4.
        tags: MDS tag dict.
        start_date: ISO date string.
        render_template_as_native_obj: must be True per RFD 0011 §4.

    Returns:
        Airflow DAG object.
    """
    dag = DAG(
        dag_id=dag_id,
        default_args=default_args,
        schedule=schedule,
        catchup=catchup,
        tags=tags,
        start_date=start_date,
        render_template_as_native_obj=render_template_as_native_obj,
    )

    with dag:
        DatabricksRunNowOperator(
            task_id="run_databricks_job",
            databricks_conn_id=params["databricks_conn_id"],
            job_name=params["job_name"],
            notebook_params={
                "partition_key": params["partition_key"],
                "execution_date": "{{ ds }}",
            },
            pool=params["pool"],
            pool_slots=params["pool_slots"],
            deferrable=True,  # RFD 0011 §6 — async-friendly
        )

    return dag
